1	export type Cell = [number, number];
2	
3	const keyOf = ([x, y]: Cell): string => `${x},${y}`;
4	
5	const neighborsOf = ([x, y]: Cell): Cell[] => [
6	  [x - 1, y - 1],
7	  [x, y - 1],
8	  [x + 1, y - 1],
9	  [x - 1, y],
10	  [x + 1, y],
11	  [x - 1, y + 1],
12	  [x, y + 1],
13	  [x + 1, y + 1],
14	];
15	
16	// Rule 1: a live cell with fewer than two live neighbors dies.
17	const diesOfUnderpopulation = (liveNeighbors: number): boolean =>
18	  liveNeighbors < 2;
19	
20	// Rule 3: a live cell with more than three live neighbors dies.
21	const diesOfOverpopulation = (liveNeighbors: number): boolean =>
22	  liveNeighbors > 3;
23	
24	// Rule 2: a live cell with two or three live neighbors lives on.
25	const survives = (liveNeighbors: number): boolean =>
26	  !diesOfUnderpopulation(liveNeighbors) &&
27	  !diesOfOverpopulation(liveNeighbors);
28	
29	// Rule 4: a dead cell with exactly three live neighbors becomes alive.
30	const isBorn = (liveNeighbors: number): boolean => liveNeighbors === 3;
31	
32	export function nextGeneration(liveCells: Cell[]): Cell[] {
33	  const living = new Set(liveCells.map(keyOf));
34	
35	  const liveNeighborCount = (cell: Cell): number =>
36	    neighborsOf(cell).filter((neighbor) => living.has(keyOf(neighbor))).length;
37	
38	  const candidates = new Map<string, Cell>();
39	  for (const cell of liveCells) {
40	    candidates.set(keyOf(cell), cell);
41	    for (const neighbor of neighborsOf(cell)) {
42	      candidates.set(keyOf(neighbor), neighbor);
43	    }
44	  }
45	
46	  const nextLiveCells: Cell[] = [];
47	  for (const [cellKey, cell] of candidates) {
48	    const liveNeighbors = liveNeighborCount(cell);
49	    const livesOn = living.has(cellKey)
50	      ? survives(liveNeighbors)
51	      : isBorn(liveNeighbors);
52	    if (livesOn) {
53	      nextLiveCells.push(cell);
54	    }
55	  }
56	
57	  return nextLiveCells;
58	}
